package com.example.smartpantrymanager.ui;
import android.os.*;import android.text.TextUtils;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.smartpantrymanager.R;import com.example.smartpantrymanager.data.DatabaseHelper;import com.example.smartpantrymanager.model.PantryItem;
public class AddEditIngredientActivity extends AppCompatActivity{DatabaseHelper db;EditText name,qty,unit,expiry;long id=-1;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_add_edit);db=new DatabaseHelper(this);name=findViewById(R.id.etName);qty=findViewById(R.id.etQty);unit=findViewById(R.id.etUnit);expiry=findViewById(R.id.etExpiry);id=getIntent().getLongExtra("id",-1);if(id!=-1){setTitle("Edit Ingredient");PantryItem p=db.getPantryItem(id);if(p!=null){name.setText(p.getName());qty.setText(String.valueOf(p.getQuantity()));unit.setText(p.getUnit());expiry.setText(p.getExpiryDate());}}findViewById(R.id.btnSave).setOnClickListener(v->save());}void save(){String n=name.getText().toString().trim(),u=unit.getText().toString().trim(),q=qty.getText().toString().trim(),e=expiry.getText().toString().trim();if(TextUtils.isEmpty(n)||TextUtils.isEmpty(u)||TextUtils.isEmpty(q)){Toast.makeText(this,"Name, quantity and unit are required",Toast.LENGTH_SHORT).show();return;}try{double d=Double.parseDouble(q);if(d<=0)throw new NumberFormatException();if(id==-1)db.addPantry(n,d,u,e);else db.updatePantry(id,n,d,u,e);finish();}catch(NumberFormatException ex){qty.setError("Enter a quantity greater than 0");}}}
